// Verifies HMAC-SHA256 signature, timestamp window and payload shape.
// Nothing in the body is processed until authenticity is cryptographically proven.
const crypto = require('crypto');

const secret = $env.N8N_SIGNING_SECRET;
if (!secret) {
  throw new Error('N8N_SIGNING_SECRET is not configured in the n8n environment');
}

const MAX_AGE_SECONDS = 300;

const reject = (reason) => {
  console.warn('[LendLoop][webhook] rejected: ' + reason);
  return [{ json: { valid: false, duplicate: false, reason } }];
};

const first = $input.first().json;
const headers = first.headers || {};
const rawSigHeader = String(headers['x-lendloop-signature'] || '');
let timestamp = String(headers['x-lendloop-timestamp'] || '');

// Support both format: t=<unix_ms>,v1=<hex> and raw hex signature
let receivedSig = rawSigHeader;
if (rawSigHeader.includes('v1=')) {
  const parts = rawSigHeader.split(',');
  for (const part of parts) {
    const [k, v] = part.split('=');
    if (k === 't' && !timestamp) timestamp = v;
    if (k === 'v1') receivedSig = v;
  }
}

// Extract raw body bytes exactly as received
let rawBody;
try {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  rawBody = buffer.toString('utf8');
} catch (error) {
  rawBody = JSON.stringify(first.body || first);
}

// Parse and validate timestamp against replay attacks
let ts = Number(timestamp);
if (ts > 10000000000) {
  ts = Math.floor(ts / 1000);
}

if (!timestamp || !Number.isFinite(ts)) return reject('bad_timestamp');
if (Math.abs(Date.now() / 1000 - ts) > MAX_AGE_SECONDS) return reject('stale_timestamp');

// Compute HMAC with timestamp prefix
const expected = crypto
  .createHmac('sha256', secret)
  .update(timestamp + '.' + rawBody)
  .digest('hex');

const expectedBuf = Buffer.from(expected, 'utf8');
const givenBuf = Buffer.from(receivedSig, 'utf8');

if (expectedBuf.length !== givenBuf.length || !crypto.timingSafeEqual(expectedBuf, givenBuf)) {
  // In case sender used seconds or ms without dot
  const expectedAlt = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
  if (receivedSig !== expectedAlt) {
    return reject('bad_signature');
  }
}

let rawEvent;
try {
  rawEvent = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
} catch (error) {
  return reject('bad_json');
}

// Normalize event shape (support both { event, payload } and direct payload)
const event = {
  type: rawEvent.type || rawEvent.event,
  loanId: rawEvent.loanId || (rawEvent.payload && rawEvent.payload.loanId),
  toolName: rawEvent.toolName || (rawEvent.payload && rawEvent.payload.toolName) || 'Tool',
  startDate: rawEvent.startDate || (rawEvent.payload && rawEvent.payload.startDate) || '',
  endDate: rawEvent.endDate || (rawEvent.payload && rawEvent.payload.endDate) || '',
  actorName: rawEvent.actorName || (rawEvent.payload && (rawEvent.payload.borrowerName || rawEvent.payload.lenderName)) || 'A neighbor',
  recipient: rawEvent.recipient || {
    email: (rawEvent.payload && rawEvent.payload.borrowerEmail) || 'neighbor@lendloop.local',
    displayName: (rawEvent.payload && rawEvent.payload.borrowerName) || 'Neighbor'
  },
  eventId: rawEvent.eventId || (rawEvent.loanId ? ('evt_' + rawEvent.loanId + '_' + Date.now()) : ('evt_' + Date.now()))
};

if (!event.type || !event.loanId) {
  return reject('bad_payload');
}

// In-memory deduplication cache check
const processed = $getWorkflowStaticData('global').processed || {};
const duplicate = Boolean(processed[event.eventId] || processed[event.loanId + ':' + event.type]);

return [{ json: { valid: true, duplicate, event } }];

// Selects the appropriate friendly template using minimized event details
const event = $json.event;
const tool = event.toolName;
const range = (event.startDate && event.endDate) ? (event.startDate + ' to ' + event.endDate) : 'upcoming dates';
const other = event.actorName || 'A neighbor';

const templates = {
  'request.created': {
    subject: 'New borrow request for ' + tool,
    text: other + ' would like to borrow "' + tool + '" (' + range + '). Open LendLoop to review and approve.',
  },
  'loan.requested': {
    subject: 'New borrow request for ' + tool,
    text: other + ' would like to borrow "' + tool + '" (' + range + '). Open LendLoop to review and approve.',
  },
  'request.approved': {
    subject: 'Your request for ' + tool + ' was approved!',
    text: 'Good news: your request to borrow "' + tool + '" (' + range + ') has been approved by ' + other + '.',
  },
  'loan.approved': {
    subject: 'Your request for ' + tool + ' was approved!',
    text: 'Good news: your request to borrow "' + tool + '" (' + range + ') has been approved by ' + other + '.',
  },
  'request.declined': {
    subject: 'Update on request for ' + tool,
    text: 'Your request to borrow "' + tool + '" (' + range + ') could not be accommodated at this time.',
  },
  'loan.declined': {
    subject: 'Update on request for ' + tool,
    text: 'Your request to borrow "' + tool + '" (' + range + ') could not be accommodated at this time.',
  },
  'request.cancelled': {
    subject: 'Request for ' + tool + ' was cancelled',
    text: other + ' cancelled the request to borrow "' + tool + '" (' + range + ').',
  },
  'loan.cancelled': {
    subject: 'Request for ' + tool + ' was cancelled',
    text: other + ' cancelled the request to borrow "' + tool + '" (' + range + ').',
  },
  'request.returned': {
    subject: tool + ' has been marked returned',
    text: '"' + tool + '" was marked returned. Thank you for sharing equipment with your block!',
  },
  'loan.returned': {
    subject: tool + ' has been marked returned',
    text: '"' + tool + '" was marked returned. Thank you for sharing equipment with your block!',
  },
};

const template = templates[event.type] || {
  subject: 'Notification for ' + tool,
  text: 'There is a status update for your tool "' + tool + '".',
};

return {
  json: {
    eventId: event.eventId,
    loanId: event.loanId,
    type: event.type,
    to: event.recipient?.email || 'neighbor@lendloop.local',
    toName: event.recipient?.displayName || 'Neighbor',
    subject: template.subject,
    text: template.text,
  },
};

// MOCK notification logger (allowed by project spec).
// Prints masked PII log entry in n8n execution console.
const maskEmail = (email) => {
  const [name, domain] = String(email).split('@');
  return (name ? name[0] : '?') + '***@' + (domain || '?');
};

console.log(
  '[LendLoop][notification] ' +
    JSON.stringify({
      eventId: $json.eventId,
      loanId: $json.loanId,
      type: $json.type,
      to: maskEmail($json.to),
      subject: $json.subject,
    }),
);

return { json: { ...$json, channel: 'mock-log' } };

// Marks eventId as processed to block duplicate webhooks from notifying twice.
const staticData = $getWorkflowStaticData('global');
const processed = staticData.processed || {};
const eventId = $('Verify signature').first().json.event.eventId;

processed[eventId] = Date.now();

// Prune to maintain fixed memory footprint
const MAX_REMEMBERED = 500;
const keys = Object.keys(processed);
if (keys.length > MAX_REMEMBERED) {
  keys
    .sort((a, b) => processed[a] - processed[b])
    .slice(0, keys.length - MAX_REMEMBERED)
    .forEach((key) => delete processed[key]);
}

staticData.processed = processed;
return { json: { ok: true, eventId } };
